import type { ErrorRequestHandler, RequestHandler } from 'express';
import { classifyError, type ErrorKind } from '../../../application/errors/errorClassification';

const STATUS_BY_KIND: Readonly<Record<ErrorKind, number>> = {
  validation: 400,
  not_found: 404,
  conflict: 409,
  internal: 500,
};

/** Errors raised by Express itself (e.g. malformed JSON) carry a client status and are safe to expose. */
function clientHttpStatus(error: unknown): number | undefined {
  if (typeof error !== 'object' || error === null) {
    return undefined;
  }
  const { status, expose } = error as { status?: unknown; expose?: unknown };
  return typeof status === 'number' && status >= 400 && status < 500 && expose === true
    ? status
    : undefined;
}

export const notFoundHandler: RequestHandler = (req, res) => {
  res.status(404).json({
    error: { code: 'NOT_FOUND', message: `No route for ${req.method} ${req.path}` },
  });
};

export const errorHandler: ErrorRequestHandler = (error: unknown, _req, res, next) => {
  if (res.headersSent) {
    next(error);
    return;
  }
  const clientStatus = clientHttpStatus(error);
  if (clientStatus !== undefined) {
    res.status(clientStatus).json({
      error: { code: 'BAD_REQUEST', message: (error as Error).message },
    });
    return;
  }
  const classified = classifyError(error);
  if (classified.kind === 'internal') {
    console.error(error);
  }
  res.status(STATUS_BY_KIND[classified.kind]).json({
    error: { code: classified.code, message: classified.message, details: classified.details },
  });
};

